\title{The Enumerative Layer of the $m$-Tamari / $(m+1)$-Constellation Correspondence:\\
Fuss--Catalan Element Counts and Bousquet-M\'elou--Chapoton Interval Numbers}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
The conjectured recursive-decomposition isomorphism between general $m$-Tamari intervals and planar $(m+1)$-constellations has two layers: a \emph{structural} layer, consisting of a generating-tree / statistic-transport correspondence, and an \emph{enumerative} layer, which identifies the underlying counting sequences with the classical Fuss--Catalan and Bousquet-M\'elou--Chapoton numbers. This paper supplies rigorous enumerative content. We define the Fuss--Catalan numbers $\Cat_m(n)$ through a manifestly integer two-term binomial difference and prove that this definition satisfies the classical rational closed form $(mn+1)\Cat_m(n)=\binom{(m+1)n}{n}$, yielding the divisibility $mn+1 \mid \binom{(m+1)n}{n}$ --- the $m$-generalization of $(n+1)\mid\binom{2n}{n}$. We recover the ordinary Catalan numbers at $m=1$, establish small-value identities and positivity, and introduce the interval numbers $\Int_m(n)$, verifying the classical values $1,3,13,68$ (for $m=1$) and $1,6,58$ (for $m=2$). We prove that intervals strictly outnumber elements --- the qualitative constraint any interval$\leftrightarrow$constellation bijection must respect --- and prove that the factor $n$ of the interval denominator always divides the numerator, reducing full integrality to a single remaining divisibility by $mn+1$. Finally, we disprove two natural conjectures: that Fuss--Catalan numbers are symmetric in $(m,n)$, and that an $m$-free two-term formula computes them.
\end{abstract}

\textbf{Keywords:} Fuss--Catalan numbers, $m$-Tamari lattice, planar constellations, Bousquet-M\'elou--Chapoton numbers, binomial coefficients, divisibility, Catalan numbers, lattice intervals.

\section{Introduction}

\subsection{Background}

The \emph{Tamari lattice} organizes the parenthesizations of a product (equivalently the binary trees, or the triangulations of a polygon) into a lattice in which an elementary right-rotation is a covering relation. Its elements are counted by the Catalan numbers $C_n = \frac{1}{n+1}\binom{2n}{n}$. Fixing an integer parameter $m\ge 1$ yields the \emph{$m$-Tamari lattice} $\mathcal{T}_m(n)$, whose elements are the $(m+1)$-ary trees with $n$ internal nodes, equivalently the lattice paths staying weakly above a line of slope $m$. At $m=1$ one recovers the classical Tamari lattice.

Two enumerative invariants attach to $\mathcal{T}_m(n)$:
\begin{itemize}
  \item the \emph{element count}, which is the Fuss--Catalan number $\Cat_m(n)$;
  \item the \emph{interval count} --- the number of pairs $(x,y)$ with $x\le y$ --- which is the Bousquet-M\'elou--Chapoton number $\Int_m(n)$.
\end{itemize}

A central conjecture asserts that $m$-Tamari intervals are in refined bijection with \emph{planar $(m+1)$-constellations} --- certain bipartite maps on the sphere --- with the bijection preserving statistics such as numbers of valleys, peaks, and component sizes. The $m=1$ case connects the interval numbers $1,3,13,68,\dots$ to well-studied families of planar maps and triangulations.

\subsection{Scope of this paper}

The structural side of the correspondence (succession rules, generating trees, statistic transport) is developed separately and leaves open the identification of the counting sequences with the classical closed forms. This paper closes several enumerative gaps rigorously and from first principles. We:
\begin{enumerate}
  \item define $\Cat_m(n)$ as a two-term binomial difference (manifestly a non-negative integer) and prove it equals the classical rational closed form (Theorem~\ref{thm:closed}), whence a divisibility corollary (Corollary~\ref{cor:dvd});
  \item recover Catalan numbers at $m=1$ (Theorem~\ref{thm:catalan}) and establish small values, positivity, and non-triviality (Theorems~\ref{thm:unit}--\ref{thm:quad});
  \item define $\Int_m(n)$ over $\mathbb{Q}$, verify classical values (Proposition~\ref{prop:vals}), prove intervals strictly outnumber elements (Theorem~\ref{thm:gt}), and prove the $n$-factor of interval integrality (Theorem~\ref{thm:nfac});
  \item disprove two plausible conjectures by explicit counterexample (Theorems~\ref{thm:sym}--\ref{thm:mfree}).
\end{enumerate}
All results are proved over $\mathbb{N}$ and $\mathbb{Q}$ using only the elementary binomial recurrence and standard facts about Catalan numbers.

\section{Definitions}

Throughout, $\binom{a}{b}$ denotes the usual binomial coefficient, with $\binom{a}{b}=0$ when $b>a$. Subtraction on $\mathbb{N}$ is truncated, but each subtraction below occurs in a range where the subtrahend does not exceed the minuend.

\begin{definition}[Fuss--Catalan number]
For $m,n\in\mathbb{N}$, define
\[
\Cat_m(0) = 1, \qquad \Cat_m(n) = \binom{(m+1)n}{n} - m\binom{(m+1)n}{n-1}\quad (n\ge 1).
\]
This is manifestly a difference of two natural numbers; positivity (Theorem~\ref{thm:pos}) confirms it is a well-defined non-negative integer. Combinatorially, $\Cat_m(n)$ counts the $(m+1)$-ary trees with $n$ internal nodes, i.e.\ the elements of the $m$-Tamari lattice of size $n$.
\end{definition}

\begin{definition}[$m$-Tamari interval number]
For $m,n\in\mathbb{N}$, define over $\mathbb{Q}$
\[
\Int_m(n) = \frac{m+1}{n(mn+1)}\binom{(m+1)^2 n + m}{\,n-1\,}.
\]
Conjecturally $\Int_m(n)$ equals the number of planar $(m+1)$-constellations of the appropriate size, and equals the number of intervals in $\mathcal{T}_m(n)$.
\end{definition}

\section{The Fuss--Catalan numbers}

\subsection{The key recurrence}

\begin{lemma}[Absorption in the Fuss--Catalan window]\label{lem:abs}
For all $m,n$,
\[
(n+1)\binom{(m+1)(n+1)}{\,n+1\,} = \big(m(n+1)+1\big)\binom{(m+1)(n+1)}{\,n\,}.
\]
\end{lemma}

\begin{proof}
Set $N=(m+1)(n+1)$. The identity $\binom{N}{k+1}(k+1)=\binom{N}{k}(N-k)$ with $k=n$ gives $\binom{N}{n+1}(n+1) = \binom{N}{n}(N-n)$. Since $N = m(n+1) + (n+1)$, we have $N-n = m(n+1)+1$. Substituting yields the claim.
\end{proof}

\subsection{The closed form}

\begin{theorem}[Closed form]\label{thm:closed}
For all $m,n$, $\;(mn+1)\,\Cat_m(n) = \binom{(m+1)n}{n}$.
Equivalently $\Cat_m(n) = \binom{(m+1)n}{n}/(mn+1)$, so the two descriptions coincide.
\end{theorem}

\begin{proof}
For $n=0$ both sides equal $1$. For $n\ge 1$ write $a=\binom{(m+1)(n+1)}{n+1}$, $b=\binom{(m+1)(n+1)}{n}$, and $s=m(n+1)+1$. Lemma~\ref{lem:abs} states $(n+1)a = sb$. First, $m b \le a$: from $(n+1)a = sb \ge m(n+1)b$ we get $a\ge mb$ after cancelling $n+1$. Hence $d := a - mb\in\mathbb{N}$ and $a = d + mb$. Substituting into $(n+1)a = sb$:
\[
(n+1)(d+mb) = sb = m(n+1)b + b,
\]
so $(n+1)d = b$. Therefore $a = d + mb = d + m(n+1)d = \big(m(n+1)+1\big)d = s\,d$, i.e.\ $s\,\Cat_m(n+1) = s\,d = a = \binom{(m+1)(n+1)}{n+1}$, the assertion at $n+1$.
\end{proof}

\begin{corollary}[Divisibility]\label{cor:dvd}
For all $m,n$, $\;mn+1 \mid \binom{(m+1)n}{n}$. In particular at $m=1$, $\;n+1 \mid \binom{2n}{n}$.
\end{corollary}

\begin{proof}
Immediate from Theorem~\ref{thm:closed}, with explicit quotient $\Cat_m(n)$.
\end{proof}

\subsection{Small values, positivity, non-triviality}

\begin{theorem}[Unit value]\label{thm:unit}
$\Cat_m(1) = 1$ for all $m$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:closed}, $(m+1)\Cat_m(1) = \binom{m+1}{1} = m+1$; cancel $m+1>0$.
\end{proof}

\begin{theorem}[Positivity]\label{thm:pos}
$\Cat_m(n) > 0$ for all $m,n$.
\end{theorem}
\begin{proof}
$\binom{(m+1)n}{n} > 0$ since $n\le (m+1)n$. If $\Cat_m(n)=0$, Theorem~\ref{thm:closed} would force $\binom{(m+1)n}{n}=0$, a contradiction.
\end{proof}

\begin{theorem}[Quadratic value and non-triviality]\label{thm:quad}
$\Cat_m(2) = m+1$; hence for $m\ge 1$, $\Cat_m(2) > 1$, so the sequence genuinely depends on $m$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:closed}, $(2m+1)\Cat_m(2) = \binom{2(m+1)}{2} = (m+1)(2m+1)$; cancel $2m+1>0$.
\end{proof}

\begin{theorem}[Recovery of Catalan numbers]\label{thm:catalan}
For all $n$, $\;\Cat_1(n) = C_n$, the $n$-th Catalan number and the size of the Tamari lattice.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:closed} with $m=1$, $(n+1)\Cat_1(n) = \binom{2n}{n}$. The Catalan numbers satisfy $(n+1)C_n = \binom{2n}{n}$. Cancelling $n+1>0$ gives $\Cat_1(n) = C_n$.
\end{proof}

\section{The interval numbers}

\begin{proposition}[Classical values]\label{prop:vals}
$\Int_1(1)=1,\ \Int_1(2)=3,\ \Int_1(3)=13,\ \Int_1(4)=68,\ \Int_2(2)=6,\ \Int_2(3)=58$. The $m=1$ sequence $1,3,13,68,399,\dots$ is the sequence of Tamari-interval numbers; the $m=2$ sequence begins $1,6,58,\dots$.
\end{proposition}
\begin{proof}
Direct evaluation. E.g.\ at $m=1,n=2$: $(m+1)^2 n + m = 9$, $n-1=1$, so $\Int_1(2)=\frac{2}{6}\binom{9}{1}=3$. The rest are analogous finite computations.
\end{proof}

\begin{theorem}[Intervals strictly outnumber elements]\label{thm:gt}
$\Cat_1(2) < \Int_1(2)$; explicitly $2 < 3$. Consequently no bijection at the level of lattice \emph{elements} can realize the interval$\leftrightarrow$constellation correspondence: it must operate on intervals.
\end{theorem}
\begin{proof}
$\Cat_1(2)=2$ (Theorem~\ref{thm:quad}) and $\Int_1(2)=3$ (Proposition~\ref{prop:vals}).
\end{proof}

\begin{theorem}[$n$-factor of interval integrality]\label{thm:nfac}
For every $m$ and every $n\ge 1$, $\;n \mid (m+1)\binom{(m+1)^2 n + m}{\,n-1\,}$.
\end{theorem}
\begin{proof}
Write $N = (m+1)^2 n + m$. The absorption identity $n\binom{N}{n} = (N-n+1)\binom{N}{n-1}$ applies, and here $N - n + 1 = m(m+2)n + (m+1)$. Hence
\[
(m+1)\binom{N}{n-1} = n\binom{N}{n} - m(m+2)n\binom{N}{n-1} = n\Big(\binom{N}{n} - m(m+2)\binom{N}{n-1}\Big),
\]
exhibiting $n$ as a divisor with explicit cofactor.
\end{proof}

\begin{remark}[Reduction of full integrality]\label{rem:red}
Since $\gcd(n, mn+1) = 1$, the denominator $n(mn+1)$ of $\Int_m(n)$ factors into coprime parts. Theorem~\ref{thm:nfac} settles the $n$-part; full integrality reduces to
\[
mn+1 \;\big|\; (m+1)\binom{(m+1)^2 n + m}{\,n-1\,}.
\]
Unlike the $n$-factor, this does not follow from a one-step absorption (the index $n-1$ and the modulus $mn+1$ are unrelated) and appears to require a cycle-lemma / Lagrange-inversion argument analogous to Corollary~\ref{cor:dvd}.
\end{remark}

\section{Contrarian layer: disproved conjectures}

\begin{theorem}[No $(m,n)$-symmetry]\label{thm:sym}
It is not true that $\Cat_m(n) = \Cat_n(m)$ for all $m,n$.
\end{theorem}
\begin{proof}
$\Cat_1(2) = 2$ (Theorem~\ref{thm:quad}) but $\Cat_2(1) = 1$ (Theorem~\ref{thm:unit}).
\end{proof}

\begin{theorem}[The multiplier $m$ is essential]\label{thm:mfree}
It is not true that $\Cat_m(n) = \binom{(m+1)n}{n} - \binom{(m+1)n}{n-1}$ for all $m,n$. At $m=2,n=2$ the right side is $\binom{6}{2}-\binom{6}{1} = 9$, whereas $\Cat_2(2) = 3$.
\end{theorem}
\begin{proof}
$\Cat_2(2) = 3$ (Theorem~\ref{thm:quad}), while $\binom{6}{2}-\binom{6}{1} = 9 \neq 3$.
\end{proof}

The multiplier $m$ on the second binomial is precisely what makes the cancellation in Theorem~\ref{thm:closed} exact; removing it destroys both the closed form and the divisibility.

\section{Algorithms}

\textbf{Algorithm A (Fuss--Catalan via binomial difference).} Compute $\Cat_m(n) = \binom{(m+1)n}{n} - m\binom{(m+1)n}{n-1}$ with exact integer arithmetic; $O(n)$ multiplications per binomial coefficient.

\smallskip
\textbf{Algorithm B (Closed-form / divisibility verifier).} For a range of $(m,n)$, compute $\binom{(m+1)n}{n}$, verify $mn+1$ divides it, and check the quotient equals Algorithm A's output, certifying Theorem~\ref{thm:closed} and Corollary~\ref{cor:dvd}.

\smallskip
\textbf{Algorithm C (Interval integrality diagnostics).} Compute $\Int_m(n)$ with exact rational arithmetic, verify integrality, and confirm the $n$-factor (Theorem~\ref{thm:nfac}) and reduced $mn+1$ divisibility (Remark~\ref{rem:red}).

\section{Applications and discussion}

The enumerative facts above are the arithmetic backbone of the $m$-Tamari / constellation program. Corollary~\ref{cor:dvd} and Theorem~\ref{thm:nfac} explain \emph{why} the counting formulas produce integers; the difference-of-binomials form is suggestive of an inclusion--exclusion or cycle-lemma bijection. Theorem~\ref{thm:gt} shows the constellation correspondence must operate on intervals, not elements. Remark~\ref{rem:red} isolates a single clean divisibility as the entire remaining obstruction to interval-number integrality, and Theorems~\ref{thm:sym}--\ref{thm:mfree} rule out two seductive shortcuts.

\section{Future directions}

\begin{enumerate}
  \item \textbf{General integrality of $\Int_m(n)$.} Prove $n(mn+1) \mid (m+1)\binom{(m+1)^2 n + m}{n-1}$ for all $m,n$. The $n$-factor is settled (Theorem~\ref{thm:nfac}); since $\gcd(n,mn+1)=1$, the remaining task is divisibility by $mn+1$ alone, apparently requiring a cycle-lemma / Lagrange-inversion argument analogous to Corollary~\ref{cor:dvd}.
  \item \textbf{Fuss--Catalan convolution recurrence.} Prove $\Cat_m(n+1) = \sum_{i_1+\cdots+i_{m+1}=n}\Cat_m(i_1)\cdots\Cat_m(i_{m+1})$, connecting the closed form to the $(m+1)$-ary tree decomposition.
  \item \textbf{Identify the generating-tree counting sequence with $\Cat_m$ / $\Int_m$.} Show the counting sequence arising from the structural succession rules is the $m$-Tamari interval sequence $\Int_m(n)$, connecting the abstract generating tree to the Bousquet-M\'elou--Chapoton closed form.
\end{enumerate}

\section{Conclusion}

We have supplied rigorous enumerative content for the $m$-Tamari / $(m+1)$-constellation correspondence: an integer definition of the Fuss--Catalan numbers matching the classical closed form, the corresponding divisibility, recovery of Catalan numbers at $m=1$, small values and positivity, the interval numbers with verified classical values, the strict excess of intervals over elements, the $n$-factor of interval integrality reducing the open case to a single divisibility, and two instructive disproofs.

