from math import comb

def fuss_catalan(m: int, n: int) -> int:
    """Cat_m(n) = C((m+1)n, n) - m*C((m+1)n, n-1); a manifest integer."""
    if n == 0:
        return 1
    return comb((m + 1) * n, n) - m * comb((m + 1) * n, n - 1)

def verify_closed_form(max_m: int = 5, max_n: int = 10) -> bool:
    """Check (m*n+1)*Cat_m(n) == C((m+1)n, n) and (m*n+1) | C((m+1)n, n)."""
    for m in range(1, max_m + 1):
        for n in range(0, max_n + 1):
            rhs = comb((m + 1) * n, n)
            if (m * n + 1) * fuss_catalan(m, n) != rhs:
                return False
            if rhs % (m * n + 1) != 0:
                return False
    return True

if __name__ == "__main__":
    print("Closed form and divisibility hold:", verify_closed_form())
    for m in range(1, 5):
        print(f"m={m}:", [fuss_catalan(m, n) for n in range(8)])

from math import comb

def fuss_catalan(m: int, n: int) -> int:
    if n == 0:
        return 1
    return comb((m + 1) * n, n) - m * comb((m + 1) * n, n - 1)

def catalan(n: int) -> int:
    """Ordinary Catalan number C_n = C(2n, n)/(n+1)."""
    return comb(2 * n, n) // (n + 1)

def recovers_catalan(max_n: int = 15) -> bool:
    """Cat_1(n) == catalan(n) for all n up to max_n."""
    return all(fuss_catalan(1, n) == catalan(n) for n in range(max_n + 1))

if __name__ == "__main__":
    print("Cat_1(n):", [fuss_catalan(1, n) for n in range(11)])
    print("catalan :", [catalan(n) for n in range(11)])
    print("Match   :", recovers_catalan())
    print("Cat_m(2) == m+1:", all(fuss_catalan(m, 2) == m + 1 for m in range(8)))

from fractions import Fraction
from math import comb, gcd

def interval_number(m: int, n: int) -> Fraction:
    """Int_m(n) = (m+1)/(n*(m*n+1)) * C((m+1)^2 n + m, n-1), exactly."""
    top = comb((m + 1) ** 2 * n + m, n - 1)
    return Fraction(m + 1) * Fraction(top, n * (m * n + 1))

def fuss_catalan(m: int, n: int) -> int:
    if n == 0:
        return 1
    return comb((m + 1) * n, n) - m * comb((m + 1) * n, n - 1)

def diagnostics(m: int, n: int) -> dict:
    """Report coprimality, factor divisibilities, integrality, and excess."""
    num = (m + 1) * comb((m + 1) ** 2 * n + m, n - 1)
    iv = interval_number(m, n)
    return {
        "coprime_n_mn1": gcd(n, m * n + 1) == 1,
        "n_divides_numerator": num % n == 0,
        "mn1_divides_numerator": num % (m * n + 1) == 0,
        "interval_is_integer": iv.denominator == 1,
        "intervals_exceed_elements": iv > fuss_catalan(m, n),
    }

if __name__ == "__main__":
    print("m=1:", [int(interval_number(1, n)) for n in range(1, 6)])
    print("m=2:", [int(interval_number(2, n)) for n in range(1, 4)])
    for m in range(1, 3):
        for n in range(1, 5):
            print(f"m={m} n={n}:", diagnostics(m, n))

