def fuss_catalan(m: int, n: int) -> int:
    """Fuss-Catalan number Cat_m(n) as a two-term binomial difference.

    Cat_m(0) = 1; for n >= 1,
        Cat_m(n) = C((m+1)n, n) - m * C((m+1)n, n-1),
